"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["87168"],{35911(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_valor_dominio.ordem_sem_todos_os_valores","status":422,"titulo":"A ordem deve trazer todos os valores do fato"},"descricao":{"codigo":"uniplus.configuracao.fato_valor_dominio.ordem_sem_todos_os_valores","requisitos":["UNI-REQ-0159"],"oQueAconteceu":["O administrador enviou a nova ordem dos valores de um fato (`PUT /api/configuracao/admin/fatos-candidato/{id}/ordem-dos-valores`) sem incluir todos os valores dele. A ordem \xe9 definida sobre o conjunto inteiro, inclusive os valores desativados, para que nenhum fique sem posi\xe7\xe3o definida. A corre\xe7\xe3o da ordem das op\xe7\xf5es de um fato \xe9 regra do UNI-REQ-0159; a lista completa e sem repeti\xe7\xe3o \xe9 a forma que a API exige para aplic\xe1-la de uma vez.","A recusa vem na lista `errors` da resposta, com `field` igual a `codigos`, e a mensagem diz o que corrigir. A ordem dos valores do fato n\xe3o \xe9 alterada. Se a lista tiver mais de um problema, cada um vem numa entrada pr\xf3pria da mesma resposta. Os espa\xe7os nas pontas de cada c\xf3digo s\xe3o desconsiderados, mas mai\xfasculas e min\xfasculas contam: `eja` n\xe3o \xe9 o mesmo valor que `EJA`."],"comoResolver":["Envie a lista completa: todos os valores do fato, ativos e desativados, cada um uma vez e s\xf3 com c\xf3digos do fato. Os c\xf3digos que faltaram v\xeam citados na mensagem desta recusa; inclua-os na posi\xe7\xe3o desejada e envie de novo. Se o mesmo valor aparece ao mesmo tempo como ausente e, na recusa de c\xf3digo desconhecido, com outra grafia, corrija as mai\xfasculas e min\xfasculas do c\xf3digo enviado."],"ondeAparece":["Reordena\xe7\xe3o dos valores de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato valor dominio"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);